const PASS = "pass"
const SKIP = "skip"
const COUNTS = [0, 0, 0]
const ONLY = isempty(ARGS) ? nothing : ARGS[1]
function t(name::String, body::Function)
  (ONLY !== nothing && !occursin(ONLY, name)) && return
  t0 = time()
  got = try
    string(body())
  catch e
    "error: " * first(sprint(showerror, e), 300)
  end
  s = round(time() - t0; digits = 2)
  mark = got == PASS ? "ok  " : got == SKIP ? "skip" : "FAIL"
  COUNTS[got == PASS ? 1 : got == SKIP ? 3 : 2] += 1
  println(mark, " ", name, " (", s, " s)", got == PASS || got == SKIP ? "" : " - " * replace(got, r"\s*\n\s*" => " "))
  flush(stdout)
end

